#include <iostream>

int x = 1; // Global scope

void useLocal() {
    int x = 25; // Reinitialized on each call
    std::cout << "local x in useLocal is " << x << " after entering\n";
    ++x;
    std::cout << "local x in useLocal is " << x << " before exiting\n";
}

void useStaticLocal() {
    static int x = 50; // Initialized once
    std::cout << "local static x is " << x << " on entering\n";
    ++x;
    std::cout << "local static x is " << x << " on exiting\n";
}

void useGlobal() {
    std::cout << "global x is " << x << " on entering\n";
    x *= 10;
    std::cout << "global x is " << x << " on exiting\n";
}

int main() {
    int x = 5; // Local to main
    std::cout << "local x in outer scope of main is " << x << "\n";

    { // Inner nested block
        int x = 7;
        std::cout << "local x in inner scope of main is " << x << "\n";
    }

    std::cout << "local x in outer scope of main is " << x << "\n";

    useLocal();
    useStaticLocal();
    useGlobal();
    useLocal();
    useStaticLocal();
    useGlobal();

    std::cout << "local x in main is " << x << "\n";
    return 0;
}

#include <iostream>

// Recursive factorial implementation
unsigned long long factorialRecursive(unsigned int n) {
    if (n <= 1) { // Base cases: 0! = 1, 1! = 1
        return 1;
    }
    return n * factorialRecursive(n - 1); // Recursive step
}

// Iterative factorial implementation
unsigned long long factorialIterative(unsigned int n) {
    unsigned long long result = 1;
    for (unsigned int counter = n; counter >= 1; --counter) {
        result *= counter;
    }
    return result;
}

int main() {
    const unsigned int number = 5;
    std::cout << "Iterative " << number << "! = " << factorialIterative(number) << "\n";
    std::cout << "Recursive " << number << "! = " << factorialRecursive(number) << "\n";
    return 0;
}
